  function renderAutomations(){
    const autos=state.automations||[];
    const rules=[
      ['inactive30','Cliente sin visitar en 30 días','Preparar una promoción de recuperación','Clientes inactivos'],
      ['reward500','Cliente alcanza 500 puntos','Avisar que ya puede canjear','Cerca de recompensa'],
      ['birthday','Cumpleaños del mes','Preparar beneficio de cumpleaños','Cumpleañeros'],
      ['campaignEnd','Promoción por terminar','Avisar al administrador','Campañas activas'],
      ['lowBranch','Sucursal con pocas visitas','Generar alerta','Rendimiento de sucursal']
    ];
    return `${pageHead('AUTOMATIZACIONES','Haz que Centro I.A. trabaje solo','Reglas que detectan momentos importantes y preparan la siguiente acción para el negocio.',`<span class="small-tag mint">${autos.filter(a=>a.enabled).length} activas</span>`)}<div class="grid two-col"><section class="panel"><div class="panel-head"><div><h3 class="panel-title">Reglas inteligentes</h3><div class="panel-sub">Activa solo las que quieras utilizar.</div></div><div class="soft-icon mint">${I('bolt')}</div></div><div class="benefit-list">${rules.map(([id,title,desc,seg])=>{const a=autos.find(x=>x.id===id)||{enabled:id!=='lowBranch'};return `<div class="benefit-row automation-row"><div class="benefit-mark ${a.enabled?'mint':'gray'}">${I(a.enabled?'checkCircle':'clock')}</div><div class="benefit-info"><div class="benefit-title">${title}</div><div class="benefit-desc">${desc} · ${seg}</div></div><button class="toggle ${a.enabled?'on':''}" data-action="toggle-automation" data-id="${id}" aria-label="${a.enabled?'Desactivar':'Activar'} ${title}"><span></span></button></div>`}).join('')}</div></section><aside class="panel"><div class="panel-head"><div><h3 class="panel-title">Cómo funciona</h3><div class="panel-sub">Primero detecta, después sugiere.</div></div><div class="soft-icon peach">${I('sparkles')}</div></div><div class="step-list"><div><b>1</b><span>Centro I.A. revisa los eventos y clientes autorizados.</span></div><div><b>2</b><span>Identifica una condición como inactividad o recompensa.</span></div><div><b>3</b><span>Prepara una acción; el envío requiere consentimiento e integración.</span></div></div><div class="footnote">En producción estas reglas deben ejecutarse en servidor y quedar registradas en auditoría.</div></aside></div>`;
  }
  function renderReferrals(){
    const r=state.referrals||{enabled:true,customerBonus:100,friendBonus:100,total:18,converted:7};
    return `${pageHead('REFERIDOS','Convierte clientes en embajadores','Cada cliente puede invitar a una persona nueva y ambos reciben un beneficio después de una compra válida.',`<button class="btn btn-primary" data-action="toggle-referrals">${r.enabled?'Programa activo':'Activar programa'} ${I('arrow')}</button>`)}<div class="grid segment-grid"><div class="segment-card"><span class="small-tag">Invitaciones</span><div class="seg-number">${r.total}</div><p>Referidos registrados en la demo.</p></div><div class="segment-card"><span class="small-tag mint">Convertidos</span><div class="seg-number">${r.converted}</div><p>Invitados que hicieron su primera compra.</p></div><div class="segment-card"><span class="small-tag peach">Conversión</span><div class="seg-number">${r.total?Math.round(r.converted/r.total*100):0}%</div><p>De invitación a primera compra.</p></div></div><section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Reglas del programa</h3><div class="panel-sub">Los puntos se entregan solo después de una compra válida.</div></div><div class="soft-icon">${I('usersPlus')}</div></div><div class="form-grid"><div class="field"><label>Puntos para quien invita</label><input id="ref-customer" type="number" min="0" value="${r.customerBonus}"></div><div class="field"><label>Puntos para el invitado</label><input id="ref-friend" type="number" min="0" value="${r.friendBonus}"></div></div><div class="modal-actions"><button class="btn btn-light" data-action="save-referrals">Guardar reglas ${I('check')}</button></div><div class="footnote">Cada código debe ser único, tener límite de uso y quedar asociado a la empresa y cliente correctos.</div></section>`;
  }
  function renderSecurity(){
    const logs=state.auditLog||[];
    return `${pageHead('CONTROL Y AUDITORÍA','Seguridad y trazabilidad','Una vista para detectar operaciones sensibles, duplicados y cambios importantes.',`<span class="small-tag mint">${logs.length} eventos</span>`)}<div class="grid segment-grid"><div class="segment-card"><span class="small-tag peach">Protección</span><div class="seg-number">RLS</div><p>La versión productiva debe aislar los datos por empresa.</p></div><div class="segment-card"><span class="small-tag mint">Antifraude</span><div class="seg-number">Activo</div><p>Reglas de ejemplo para visitas y canjes repetidos.</p></div><div class="segment-card"><span class="small-tag">Consentimiento</span><div class="seg-number">Obligatorio</div><p>Las campañas externas deben respetar el consentimiento.</p></div></div><section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Registro de operaciones</h3><div class="panel-sub">Quién hizo qué y cuándo.</div></div><div class="soft-icon peach">${I('shield')}</div></div><div class="benefit-list">${logs.length?logs.slice(0,12).map(x=>`<div class="benefit-row"><div class="benefit-mark mint">${I('shield')}</div><div class="benefit-info"><div class="benefit-title">${escapeHTML(x.action)}</div><div class="benefit-desc">${escapeHTML(x.detail||'Operación registrada')} · ${escapeHTML(x.date||'Ahora')}</div></div><span class="small-tag gray">${escapeHTML(x.actor||'Sistema')}</span></div>`).join(''):'<div class="empty-note">Todavía no hay operaciones sensibles registradas.</div>'}</div><div class="footnote">El registro de auditoría de producción debe ser append-only y no editable desde la interfaz normal.</div></section>`;
  }
  function renderSettings(){
    const cfg=state.settings||{plan:'Estándar',industry:'Café y comida',modules:{events:true,analytics:true,automations:true,referrals:true}};
    const modes=[['Básica','Puntos, clientes, canjes y promociones sencillas.'],['Estándar','Sucursales, estadísticas, calendario y campañas automáticas.'],['Personalizada','Activa o desactiva módulos y reglas propias.']];
    return `${pageHead('CONFIGURACIÓN','Adapta Centro I.A. a tu negocio','Elige el nivel de experiencia y los módulos que realmente necesitas.',`<span class="small-tag">${escapeHTML(cfg.plan)}</span>`)}<section class="panel"><div class="panel-head"><div><h3 class="panel-title">Modalidad</h3><div class="panel-sub">Puedes cambiarla sin perder la información de la demo.</div></div><div class="soft-icon">${I('settings')}</div></div><div class="plan-grid">${modes.map(([name,desc])=>`<button class="plan-option ${cfg.plan===name?'selected':''}" data-action="set-plan" data-plan="${name}"><span>${cfg.plan===name?I('checkCircle'):I('circle')}</span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div></section><section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Módulos</h3><div class="panel-sub">Controla qué aparece en tu experiencia.</div></div></div><div class="benefit-list">${[['events','Eventos y calendario'],['analytics','Reportes y estadísticas'],['automations','Automatizaciones'],['referrals','Programa de referidos']].map(([id,label])=>`<div class="benefit-row"><div class="benefit-info"><div class="benefit-title">${label}</div><div class="benefit-desc">Disponible para el negocio y sus empleados según permisos.</div></div><button class="toggle ${cfg.modules[id]?'on':''}" data-action="toggle-module" data-id="${id}"><span></span></button></div>`).join('')}</div><div class="footnote">La conexión real con Supabase, autenticación, RLS y copias de seguridad debe configurarse antes de usar datos reales.</div></section><section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Integraciones y operación real</h3><div class="panel-sub">Deja preparado el camino para producción.</div></div><div class="soft-icon">${I('bolt')}</div></div><div class="integration-grid"><div><strong>Supabase</strong><span>Auth + base de datos + RLS</span><b>Por conectar</b></div><div><strong>Gemini</strong><span>Centro I.A. inteligente</span><b>Por conectar</b></div><div><strong>WhatsApp</strong><span>Campañas autorizadas</span><b>Por conectar</b></div><div><strong>Correo / SMS</strong><span>Canales de comunicación</span><b>Por conectar</b></div></div><div class="role-list"><span>Propietario</span><span>Administrador</span><span>Supervisor</span><span>Empleado</span></div><div class="footnote">La conexión real con Supabase, autenticación, RLS, copias de seguridad y proveedores de mensajería debe configurarse antes de usar datos reales.</div></section>`;
  }
  function renderCustomer360(){
    const clients=[...fidSeed,...(state.customCustomers||[])], total=clients.length, visits=clients.reduce((a,c)=>a+Number(c.visits||0),0), pts=clients.reduce((a,c)=>a+Number(c.points||0),0), avg=total?Math.round(clients.reduce((a,c)=>a+Number(c.spend||0),0)/total):0;
    return `${pageHead('PERFIL 360°','Conoce a cada cliente','Centro I.A. convierte cada perfil en una lectura de relación: fidelidad, riesgo, valor y siguiente acción.',`<button class="btn btn-primary" data-action="nexo-open">${I('brain')} Abrir Centro I.A.</button>`)}
    <div class="grid kpi-grid"><div class="kpi-card"><div class="kpi-icon">${I('users')}</div><div class="kpi-label">Clientes</div><div class="kpi-value">${total}</div><div class="kpi-note">Personas conocidas por Centro I.A.</div></div><div class="kpi-card"><div class="kpi-icon">${I('activity')}</div><div class="kpi-label">Visitas registradas</div><div class="kpi-value">${visits}</div><div class="kpi-note">Historial acumulado</div></div><div class="kpi-card"><div class="kpi-icon">${I('gift')}</div><div class="kpi-label">Puntos</div><div class="kpi-value">${pts.toLocaleString('es-MX')}</div><div class="kpi-note">En circulación</div></div><div class="kpi-card"><div class="kpi-icon">${I('target')}</div><div class="kpi-label">Valor promedio</div><div class="kpi-value">$${avg.toLocaleString('es-MX')}</div><div class="kpi-note">Demostración</div></div></div>
    <section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Lectura de fidelidad</h3><div class="panel-sub">El índice combina recencia, frecuencia, visitas, puntos y nivel. Es orientativo en esta demo.</div></div><label class="search-wide">${I('search')}<input data-customer-search placeholder="Buscar cliente..."></label></div><div class="table-wrap"><table class="list-table"><thead><tr><th>Cliente</th><th>Fidelidad</th><th>Riesgo</th><th>Última visita</th><th>Puntos</th><th>Siguiente acción</th><th></th></tr></thead><tbody>${clients.map(c=>{const score=fidScore(c),risk=fidRisk(c),action=risk==='Alto'?'Recuperar':Number(c.points||0)>=REW?'Reconocer':'Mantener relación';return `<tr><td><div class="table-person"><span class="avatar avatar-small">${escapeHTML(c.initials||c.name.slice(0,2).toUpperCase())}</span><div><strong>${escapeHTML(c.name)}</strong><small>${escapeHTML(c.fav||c.tier||c.status||'Cliente del programa')}</small></div></div></td><td><div class="score-cell"><b>${score}</b><span><i style="width:${score}%"></i></span></div></td><td><span class="small-tag ${risk==='Alto'?'peach':'mint'}">${risk}</span></td><td>${escapeHTML(c.last||'—')}</td><td><strong>${c.points||0}</strong></td><td>${action}</td><td><button class="inline-link" data-action="profile360" data-id="${escapeHTML(c.id)}">Ver perfil ${I('chevron')}</button></td></tr>`}).join('')}</tbody></table></div></section>`;
  }

  function renderRecovery(){
    const risk=fidSeed.filter(fidInactive).sort((a,b)=>b.days-a.days), near=fidSeed.filter(fidNear), birthdays=fidSeed.filter(c=>c.bday===new Date().getMonth());
    return `${pageHead('RECUPERAR, NO PERDER','Clientes que necesitan atención','Centro I.A. detecta cuándo alguien dejó de regresar respecto a su ritmo habitual y propone una acción concreta.',`<button class="btn btn-primary" data-action="campaign-for" data-segment="Clientes inactivos">${I('megaphone')} Crear campaña de recuperación</button>`)}
    <div class="grid segment-grid"><div class="segment-card"><span class="small-tag peach">En riesgo</span><div class="seg-number">${risk.length}</div><p>Clientes que llevan más tiempo del esperado sin volver.</p></div><div class="segment-card"><span class="small-tag mint">Cerca</span><div class="seg-number">${near.length}</div><p>Están cerca de una recompensa y pueden necesitar un pequeño empujón.</p></div><div class="segment-card"><span class="small-tag">Oportunidad</span><div class="seg-number">${birthdays.length}</div><p>Clientes con una ocasión especial que puedes convertir en regreso.</p></div></div>
    <section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">¿Por qué no regresa?</h3><div class="panel-sub">Hipótesis de comportamiento para priorizar acciones.</div></div><button class="btn btn-light btn-small" data-action="nexo-open">Abrir Centro I.A.</button></div><div class="insight-grid"><div class="insight-card"><div class="insight-icon peach">${I('clockAlert')}</div><strong>Ritmo roto</strong><p>${risk.length?`${risk[0].name} suele volver cada 10–15 días y ya lleva ${risk[0].days} días sin visita.`:'No hay suficiente historial todavía.'}</p><button class="inline-link" data-action="profile360" data-id="${risk[0]?.id||''}">Ver cliente ${I('chevron')}</button></div><div class="insight-card"><div class="insight-icon mint">${I('gift')}</div><strong>Motivo para volver</strong><p>${near.length?`${near[0].name} está a ${REW-near[0].points} puntos de su recompensa.`:'No hay clientes cerca de recompensa.'}</p><button class="inline-link" data-action="campaign-for" data-segment="Cerca de recompensa">Crear incentivo ${I('chevron')}</button></div><div class="insight-card"><div class="insight-icon">${I('heart')}</div><strong>Relación</strong><p>Combina frecuencia, gasto, recompensas y respuesta a promociones antes de decidir qué enviar.</p><button class="inline-link" data-action="nexo-open">Analizar con Centro I.A. ${I('chevron')}</button></div></div></section>
    <section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Prioridad de recuperación</h3><div class="panel-sub">Ordenados por días de ausencia.</div></div></div><div class="table-wrap"><table class="list-table"><thead><tr><th>Cliente</th><th>Ausencia</th><th>Puntos</th><th>Acción sugerida</th><th></th></tr></thead><tbody>${risk.map(c=>`<tr><td><strong>${escapeHTML(c.name)}</strong></td><td><span class="small-tag peach">${c.days} días</span></td><td>${c.points}</td><td>${escapeHTML(fidPromo(c).label)}</td><td><button class="btn btn-light btn-small" data-action="campaign-for" data-segment="Clientes inactivos">Preparar</button></td></tr>`).join('')}</tbody></table></div></section>`;
  }

  function renderFinalidad(){
    return `${pageHead('LA FINALIDAD DE Centro I.A.','¿Qué está pasando con tus clientes?','La finalidad no es llenar el sistema de datos: es convertirlos en decisiones que hagan que las personas quieran volver.',`<button class="btn btn-primary" data-action="nexo-open">${I('sparkles')} Abrir Centro I.A.</button>`)}
    <section class="purpose-hero"><div><span class="small-tag mint">Centro I.A.</span><h2>Entender por qué vuelven, por qué se van y qué hacer después.</h2><p>Centro I.A. une fidelidad, bitácora, campañas, eventos y comportamiento en una sola experiencia centrada en el cliente.</p></div><div class="purpose-orbit"><span>${I('users')} Clientes</span><span>${I('gift')} Fidelidad</span><span>${I('megaphone')} Promociones</span><span>${I('chart')} Resultados</span></div></section>
    <div class="grid segment-grid"><div class="segment-card"><span class="small-tag">1 · Conocer</span><div class="seg-number">360°</div><p>Perfil completo: visitas, puntos, gasto, frecuencia, favoritos y recompensas.</p></div><div class="segment-card"><span class="small-tag peach">2 · Detectar</span><div class="seg-number">15/30/60/90</div><p>Detecta clientes nuevos, frecuentes, en riesgo y perdidos según su ritmo.</p></div><div class="segment-card"><span class="small-tag mint">3 · Actuar</span><div class="seg-number">1 clic</div><p>Convierte un hallazgo en promoción, desafío, recompensa o evento.</p></div></div>
    <section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">La pregunta que guía a Centro I.A.</h3><div class="panel-sub">“¿Qué puedo hacer hoy para que mis clientes tengan un motivo para volver?”</div></div></div><div class="step-list"><div><b>01</b><span><strong>Observar:</strong> identifica cambios en frecuencia, gasto, puntos y visitas.</span></div><div><b>02</b><span><strong>Interpretar:</strong> encuentra grupos con necesidades parecidas.</span></div><div><b>03</b><span><strong>Recomendar:</strong> propone una acción concreta y medible.</span></div><div><b>04</b><span><strong>Medir:</strong> comprueba si regresaron y qué campaña funcionó.</span></div></div></section>`;
  }

  function renderResults(){
    const campaigns=state.campaigns||[];
    return `${pageHead('MARKETING CON RESULTADOS','Resultados de campañas','No basta con enviar una promoción: mide quién volvió, quién canjeó y cuánto generó.',`<button class="btn btn-primary" data-action="new-campaign">${I('plus')} Nueva campaña</button>`)}
    <div class="grid kpi-grid"><div class="kpi-card"><div class="kpi-label">Enviadas</div><div class="kpi-value">428</div><div class="kpi-note">Campañas de ejemplo</div></div><div class="kpi-card"><div class="kpi-label">Regresaron</div><div class="kpi-value">96</div><div class="kpi-note">22% de respuesta</div></div><div class="kpi-card"><div class="kpi-label">Canjes</div><div class="kpi-value">61</div><div class="kpi-note">Beneficios utilizados</div></div><div class="kpi-card"><div class="kpi-label">Ventas atribuidas</div><div class="kpi-value">$18,420</div><div class="kpi-note">Demostración</div></div></div>
    <section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Embudo de una campaña</h3><div class="panel-sub">De mensaje enviado a regreso real.</div></div></div><div class="campaign-funnel"><div><b>428</b><span>Enviadas</span></div><div><b>274</b><span>Vistas</span></div><div><b>119</b><span>Interesados</span></div><div><b>61</b><span>Canjes</span></div><div><b>42</b><span>Regresos</span></div></div></section>
    <section class="panel section-block"><div class="panel-head"><div><h3 class="panel-title">Campañas</h3><div class="panel-sub">Compara desempeño y decide qué repetir.</div></div></div><div class="table-wrap"><table class="list-table"><thead><tr><th>Campaña</th><th>Segmento</th><th>Estado</th><th>Vista</th><th>Canje</th><th>Resultado</th></tr></thead><tbody>${campaigns.map((c,i)=>`<tr><td><strong>${escapeHTML(c.title)}</strong><small>${escapeHTML(c.created||'')}</small></td><td>${escapeHTML(c.segment)}</td><td><span class="small-tag ${c.status==='Borrador'?'':'mint'}">${escapeHTML(c.status)}</span></td><td>${i===0?'64%':'58%'}</td><td>${i===0?'14%':'11%'}</td><td><strong>${i===0?'+$4,860':'+$2,940'}</strong></td></tr>`).join('')}</tbody></table></div></section>`;
  }

  function renderMain(){switch(state.tab){case'today':return renderCenterAI();case'cliente360':return renderCustomer360();case'recovery':return renderRecovery();case'finalidad':return renderFinalidad();case'results':return renderResults();case'locations':return renderLocations();case'points':return renderPoints();case'visit-calendar':return renderVisitCalendar();case'discover':return renderDiscover();case'events':return renderEventsPage();case'benefits':return renderBenefits();case'activity':return renderActivity();case'business-home':return renderAdminHome();case'fidelidad':return renderFidelidad();case'customers':return renderCustomer360();case'loyalty':return renderLoyalty();case'events-admin':return renderAdminEvents();case'campaigns':return renderCampaigns();case'reviews':return renderReviews();case'analytics':return renderAnalytics();case'automations':return renderAutomations();case'referrals':return renderReferrals();case'security':return renderSecurity();case'settings':return renderSettings();default:return isAdmin()?renderFidelidad():renderHome();}}
  function modalContent(){if(!state.modal)return '';const m=state.modal;if(m.type==='new-location'){return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><div><h2>Registrar local</h2><p>Agrega los datos de una sucursal.</p></div><button class="close-modal" data-action="close-modal">${I('close')}</button></div><form data-form="new-location"><div class="form-grid"><div class="field full"><label>Nombre del local</label><input name="name" required maxlength="100" placeholder="Sucursal Centro"></div><div class="field full"><label>Dirección</label><input name="address" required maxlength="180" placeholder="Calle, número y colonia"></div><div class="field"><label>Ciudad</label><input name="city" maxlength="80" placeholder="Ensenada, BC"></div><div class="field"><label>Enlace de mapa (opcional)</label><input name="map" type="url" placeholder="https://maps.google.com/..."></div></div><div class="modal-actions"><button type="button" class="btn btn-light" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">Guardar local</button></div></form></section></div>`;}if(m.type==='new-event'){return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><div><h2 id="modal-title">Crea una experiencia</h2><p>Publica un plan para que tu comunidad tenga algo que esperar.</p></div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">${I('close')}</button></div><form data-form="new-event"><div class="form-grid"><div class="field full"><label for="event-title">Nombre del evento</label><input id="event-title" name="title" maxlength="90" required placeholder="Ej. Noche de café y vinilos"></div><div class="field"><label for="event-category">Categoría</label><select id="event-category" name="category"><option>Comunidad</option><option>Café & comunidad</option><option>Bienestar</option><option>Taller</option><option>Experiencia VIP</option><option>Mercadito</option><option>Música</option></select></div><div class="field"><label for="event-date">Fecha</label><input id="event-date" name="date" type="date" min="${todayISO()}" required value="${offsetISO(4)}"></div><div class="field"><label for="event-time">Hora</label><input id="event-time" name="time" type="time" value="17:00" required></div><div class="field"><label for="event-price">Precio o acceso</label><input id="event-price" name="price" maxlength="45" value="Entrada libre" required></div><div class="field full"><label for="event-location">Lugar</label><input id="event-location" name="location" maxlength="100" required value="Casa Luma Café"></div><div class="field full"><label for="event-description">¿Qué va a pasar?</label><textarea id="event-description" name="description" maxlength="280" required placeholder="Cuéntale a tu comunidad por qué vale la pena asistir."></textarea></div></div><div class="modal-actions"><button type="button" class="btn btn-light" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">Publicar en la demo ${I('arrow')}</button></div><div class="footnote">El evento se guardará en este navegador; no se publicará en redes ni enviará invitaciones reales.</div></form></section></div>`;}
    if(m.type==='campaign'){const defaultTitle=m.title||'Una invitación para volver';const defaultSegment=m.segment||'Clientes inactivos';const selectedId=m.recipientId||'';const selectedCustomer=allFidCustomers().find(c=>c.id===selectedId);return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><div><h2 id="modal-title">Prepara una campaña</h2><p>Elige a quién quieres invitar. Puedes buscar por nombre y Centro I.A. te sugerirá clientes.</p></div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">${I('close')}</button></div><form data-form="campaign"><div class="form-grid"><div class="field full"><label for="campaign-recipient">Enviar a un cliente</label><div class="campaign-recipient-wrap"><div class="recipient-input-row">${I('search')}<input id="campaign-recipient" name="recipientName" autocomplete="off" placeholder="Escribe el nombre del cliente..." value="${escapeHTML(selectedCustomer?.name||'')}"><input type="hidden" id="campaign-recipient-id" name="recipientId" value="${escapeHTML(selectedId)}"></div><div class="campaign-recipient-suggestions" id="campaign-recipient-suggestions"></div>${selectedCustomer?`<div class="selected-recipient">${I('check')} Enviando a <strong>${escapeHTML(selectedCustomer.name)}</strong><button type="button" class="recipient-clear" data-action="clear-campaign-recipient">Quitar</button></div>`:''}</div><div class="field-help">Si no eliges un nombre, puedes usar el segmento para preparar una campaña para varias personas.</div></div><div class="field"><label for="campaign-title">Nombre de campaña</label><input id="campaign-title" name="title" maxlength="80" required value="${escapeHTML(defaultTitle)}"></div><div class="field"><label for="campaign-segment">O usar un grupo</label><select id="campaign-segment" name="segment"><option ${defaultSegment==='Clientes inactivos'?'selected':''}>Clientes inactivos</option><option ${defaultSegment==='Clientes frecuentes'?'selected':''}>Clientes frecuentes</option><option ${defaultSegment==='Clientes nuevos'?'selected':''}>Clientes nuevos</option><option>Miembros que siguen eventos</option><option>Todos los miembros con consentimiento</option></select></div><div class="field"><label for="campaign-channel">Canal</label><select id="campaign-channel" name="channel"><option>Notificación</option><option>Correo electrónico</option><option>WhatsApp con consentimiento</option><option>Mensaje dentro de Centro I.A.</option></select></div><div class="field full"><label for="campaign-message">Mensaje</label><textarea id="campaign-message" name="message" maxlength="500" required>${escapeHTML(defaultSegment==='Clientes inactivos'?'Hace tiempo que no nos vemos y nos encantaría recibirte de nuevo. Mira lo que estamos preparando para esta semana.':'Gracias por ser parte de nuestra comunidad. Tenemos algo nuevo que nos gustaría compartir contigo.')}</textarea></div></div><div class="modal-actions"><button type="button" class="btn btn-light" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">Guardar borrador ${I('arrow')}</button></div><div class="footnote">Se guardará como borrador. Esta demo no cuenta con envío de mensajes ni con un registro de consentimiento real.</div></form></section></div>`;}
    if(m.type==='event-details'){const e=getEvent(m.id);if(!e)return '';const going=state.rsvps.includes(e.id);return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><div><h2 id="modal-title">${escapeHTML(e.title)}</h2><p>${escapeHTML(e.category)} · organizado por ${escapeHTML(e.host)}</p></div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">${I('close')}</button></div><div class="event-image" style="height:185px;border-radius:15px;margin-bottom:15px"><img src="${escapeHTML(e.image||businesses[0].image)}" alt="" onerror="this.style.display='none'"></div><div class="benefit-list"><div class="benefit-row">${eventDateTile(e.date)}<div class="benefit-info"><div class="benefit-title">${escapeHTML(fmtDate(e.date,{weekday:'long',day:'numeric',month:'long'}))}</div><div class="benefit-desc">${escapeHTML(e.time)}</div></div></div><div class="benefit-row"><div class="benefit-mark peach">${I('pin')}</div><div class="benefit-info"><div class="benefit-title">${escapeHTML(e.location)}</div><div class="benefit-desc">${escapeHTML(e.price)}</div></div></div></div><p style="font-size:12px;line-height:1.7;color:#71718a;margin:15px 0">${escapeHTML(e.description)}</p><div class="modal-actions"><button type="button" class="btn btn-light" data-action="close-modal">Cerrar</button>${isAdmin()?'':`<button type="button" class="btn ${going?'btn-soft':'btn-primary'}" data-action="rsvp" data-id="${escapeHTML(e.id)}">${going?I('check')+' Ya me apunté':'Me interesa, guardar mi lugar'}</button>`}</div><div class="footnote">${isAdmin()?'Vista previa del evento en el prototipo.':'Tu interés se guarda solo en este prototipo; no es una reservación confirmada con el organizador.'}</div></section></div>`;}
    if(m.type==='business-detail'){const b=businesses.find(x=>x.id===m.id);if(!b)return '';const following=state.followed.includes(b.id);const related=getEvents().filter(e=>e.host===b.name||e.location===b.name).slice(0,2);return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><div><h2 id="modal-title">${escapeHTML(b.name)}</h2><p>${escapeHTML(b.category)} · ${I('star')} ${escapeHTML(b.rating)} · ${escapeHTML(b.distance)}</p></div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">${I('close')}</button></div><div class="event-image" style="height:170px;border-radius:15px;margin-bottom:15px"><img src="${escapeHTML(b.image)}" alt="" onerror="this.style.display='none'"></div><p style="font-size:12px;line-height:1.7;color:#71718a">${escapeHTML(b.description)}</p><div class="panel" style="box-shadow:none;margin:14px 0;background:#faf8ff"><div style="display:flex;align-items:center;gap:10px">${I('gift')}<div><strong>${escapeHTML(b.reward)}</strong><div class="section-caption">Beneficio ilustrativo del club</div></div></div></div><h3 class="panel-title">Próximas experiencias</h3><div class="benefit-list mt-18">${related.length?related.map(e=>`<div class="benefit-row">${eventDateTile(e.date)}<div class="benefit-info"><div class="benefit-title">${escapeHTML(e.title)}</div><div class="benefit-desc">${escapeHTML(fmtDate(e.date))} · ${escapeHTML(e.time)}</div></div><button class="inline-link" data-action="event-details" data-id="${e.id}">Ver</button></div>`).join(''):'<div class="empty-note">Este club publicará sus próximos eventos aquí.</div>'}</div><div class="modal-actions"><button class="btn btn-light" data-action="close-modal">Cerrar</button><button class="btn ${following?'btn-soft':'btn-primary'}" data-action="toggle-follow" data-id="${b.id}">${following?I('check')+' Siguiendo':'Seguir este club'}</button></div></section></div>`;}
    if(m.type==='nexo'){const chat=state.nexoChat||[];const qs=['¿A quién le mando una promo hoy?','Clientes inactivos','Quién está cerca de su recompensa','Cumpleaños del mes'];return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><div><h2 id="modal-title">Centro I.A.</h2><p>Tu asistente inteligente para decidir a quién escribirle y con qué promoción.</p></div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">${I('close')}</button></div><div class="nx-msgs" id="nx-msgs"><div class="nx-msg n">Hola, soy Centro I.A. Reviso tus clientes y te digo a quién escribirle y con qué promoción.</div>${chat.map(x=>`<div class="nx-msg ${x.r}">${escapeHTML(x.t)}</div>`).join('')}</div><div class="nx-chips">${qs.map(q=>`<button class="chip-btn" data-action="nexo-ask" data-q="${escapeHTML(q)}">${escapeHTML(q)}</button>`).join('')}</div><form class="nx-form" data-form="nexo"><input name="q" placeholder="Pregúntale a Centro I.A." autocomplete="off" aria-label="Mensaje para Centro I.A."><button class="btn btn-primary" type="submit">Enviar</button></form><div class="footnote">Vista previa con reglas locales. Gemini se conectará después para convertir este prototipo en IA real.</div></section></div>`;}
    if(m.type==='customer-preview'){const c=[...fidSeed,...customerSeed,...(state.customCustomers||[])].find(x=>x.id===m.id)||fidSeed[0];const promo=fidPromo(c);const purchases=[{name:c.fav||'Producto favorito',detail:'Compra habitual',amount:'$185'},{name:'Combo de la semana',detail:'Compra reciente',amount:'$240'},{name:'Bebida especial',detail:'Compra frecuente',amount:'$95'}];const total=(c.visits||0)*185;return `<div class="customer-preview-layer" data-action="backdrop-close"><aside class="customer-preview" role="dialog" aria-modal="true"><div class="customer-preview-top"><div class="customer-preview-identity"><div class="avatar avatar-large ${escapeHTML(c.tone||'')}">${escapeHTML(c.initials||c.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div><span class="preview-kicker">PERFIL DEL CLIENTE</span><h2>${escapeHTML(c.name)}</h2><p>${escapeHTML(c.status||c.tier||'Cliente')} · ${c.points||0} puntos</p></div></div><button class="close-modal" data-action="close-modal" aria-label="Cerrar">${I('close')}</button></div><div class="preview-summary"><div><small>Última visita</small><strong>${escapeHTML(c.last||fidLast(c.days)||'—')}</strong></div><div><small>Visitas</small><strong>${c.visits||0}</strong></div><div><small>Fidelidad</small><strong>${fidScore(c)}/100</strong></div></div><section class="preview-section"><div class="preview-section-head"><div><h3>Lo que ha comprado</h3><p>Resumen de sus compras recientes.</p></div><span class="small-tag mint">${c.visits||0} visitas</span></div><div class="preview-purchases">${purchases.map(x=>`<div class="preview-purchase"><div class="purchase-icon">${I('gift')}</div><div><strong>${escapeHTML(x.name)}</strong><span>${escapeHTML(x.detail)}</span></div><b>${x.amount}</b></div>`).join('')}</div></section><section class="preview-section"><div class="preview-section-head"><div><h3>Historial de compras</h3><p>Lo que ha comprado y cuánto generó.</p></div><span class="small-tag mint">${(state.purchases||purchaseSeed).filter(x=>x.customer===c.name).length} compras</span></div><div class="preview-purchases">${(state.purchases||purchaseSeed).filter(x=>x.customer===c.name).slice(0,5).map(x=>`<div class="preview-purchase"><div class="purchase-icon">${I('shoppingBag')}</div><div><strong>${escapeHTML(x.product)}</strong><span>${escapeHTML(fmtDate(x.date))} · ${escapeHTML(x.location)}</span></div><b>$${Number(x.amount).toLocaleString('es-MX')}</b></div>`).join('')||'<div class="empty-note">Todavía no hay compras registradas para este cliente.</div>'}</div></section><section class="preview-section"><div class="preview-section-head"><div><h3>Comportamiento</h3><p>Lo más útil para decidir qué hacer con él.</p></div></div><div class="preview-insights"><div><span>Favorito</span><strong>${escapeHTML(c.fav||'Sin registrar')}</strong></div><div><span>Valor estimado</span><strong>$${Number(total).toLocaleString('es-MX')}</strong></div><div><span>Recompensa</span><strong>${c.points>=REW?'Lista para canjear':`Faltan ${Math.max(0,REW-(c.points||0))} pts`}</strong></div></div></section><div class="preview-recommendation"><div class="soft-icon mint">${I('sparkles')}</div><div><strong>Qué podrías hacer</strong><p>${escapeHTML(promo.msg)}</p></div></div><div class="preview-actions"><button class="btn btn-light" data-action="close-modal">Cerrar</button><button class="btn btn-primary" data-action="profile360" data-id="${escapeHTML(c.id)}">Ver perfil completo ${I('arrow')}</button></div></aside></div>`;}
    if(m.type==='profile360'){const c=[...fidSeed,...(state.customCustomers||[])].find(x=>x.id===m.id)||fidSeed[0];const promo=fidPromo(c);return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal profile360-modal" role="dialog" aria-modal="true"><div class="modal-top"><div><h2>${escapeHTML(c.name)}</h2><p>Perfil 360° · ${escapeHTML(c.tier||'Bronce')} · ${c.points||0} puntos</p></div><button class="close-modal" data-action="close-modal">${I('close')}</button></div><div class="profile360-head"><div class="avatar avatar-large">${escapeHTML(c.initials||c.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div><strong>${escapeHTML(c.name)}</strong><span>${c.visits||0} visitas · última visita ${escapeHTML(c.last||'—')}</span></div></div><div class="profile360-grid"><div><small>Índice de fidelidad</small><strong>${fidScore(c)}/100</strong></div><div><small>Riesgo de abandono</small><strong>${fidRisk(c)}</strong></div><div><small>Valor estimado</small><strong>$${Number((c.visits||0)*185).toLocaleString('es-MX')}</strong></div><div><small>Recompensa</small><strong>${c.points>=REW?'Disponible':`Faltan ${Math.max(0,REW-(c.points||0))}`}</strong></div></div><div class="panel profile360-insight"><strong>${I('sparkles')} Lo que Centro I.A. sugiere</strong><p>${escapeHTML(promo.msg)} ${fidRisk(c)==='Alto'?'Conviene recuperar la relación con un mensaje personal.':fidScore(c)>=80?'Mantén la relación con reconocimiento, no necesariamente con descuento.':'Observa su próxima visita y prueba un beneficio ligero si deja de volver.'}</p></div><div class="modal-actions"><button class="btn btn-light" data-action="close-modal">Cerrar</button><button class="btn btn-primary" data-action="campaign-for" data-segment="Clientes inactivos">Crear promoción</button></div></section></div>`;}
    if(m.type==='reward-preview'){return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><div><h2>Catálogo de recompensas</h2><p>Beneficios que tus clientes pueden desbloquear con puntos.</p></div><button class="close-modal" data-action="close-modal">${I('close')}</button></div><div class="reward-modal-grid">${(state.rewards||rewardSeed).map(r=>`<div class="reward-modal-card"><div class="soft-icon mint">${I('gift')}</div><span class="small-tag mint">${escapeHTML(r.status)}</span><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.type)} · ${r.expires}</p><strong>${r.cost} pts</strong><button class="btn btn-light btn-small">Editar después</button></div>`).join('')}</div><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Cerrar</button></div></section></div>`;}
    if(m.type==='profile'){return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><div><h2>Perfil de ${isAdmin()?'tu negocio':'miembro'}</h2><p>Datos ilustrativos de esta experiencia de prueba.</p></div><button class="close-modal" data-action="close-modal">${I('close')}</button></div><div class="benefit-row"><div class="avatar">${isAdmin()?'CL':'AR'}</div><div class="benefit-info"><div class="benefit-title">${escapeHTML(isAdmin()?(businessName()):(state.authUser?.name||'Miembro'))}</div><div class="benefit-desc">${isAdmin()?'Administradora de negocio':'Miembro de Centro I.A.'}</div></div></div><div class="footnote">La identidad, inicio de sesión y datos centralizados todavía no están conectados a un backend.</div><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Entendido</button></div></section></div>`;}
    if(m.type==='notifications'){const ns=state.notifications||[];return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><div><h2>Notificaciones</h2><p>Lo importante que está pasando con tus clientes.</p></div><button class="close-modal" data-action="close-modal">${I('close')}</button></div><div class="notification-list">${ns.map(n=>`<div class="notification-row ${n.read?'read':''}"><div class="notification-icon">${I(n.kind||'sparkles')}</div><div><strong>${escapeHTML(n.title)}</strong><p>${escapeHTML(n.detail)}</p></div>${n.read?'<span class="small-tag gray">Leída</span>':`<button class="inline-link" data-action="mark-notification" data-id="${escapeHTML(n.id)}">Marcar leída</button>`}</div>`).join('')}</div><div class="footnote">Las notificaciones son de demostración. En producción se generarían desde eventos reales del negocio.</div></section></div>`;}
    return '';
  }
  function render(){const root=$('#app');if(!root)return;if(!state.introComplete){root.innerHTML=introScreen();return;}if(!state.authUser){root.innerHTML=authScreen();return;}if(state.onboarding){root.innerHTML=onboardingScreen();return;}root.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}<div class="content">${renderMain()}<footer style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:34px;padding-top:17px;border-top:1px solid #eae9f1;color:#a09fb2;font-size:10px"><span>© ${new Date().getFullYear()} Centro I.A. · Un motivo para volver.</span><span>Demo local · Para operar con clientes reales conecta autenticación y base de datos.</span></footer></div></main></div>${mobileNav()}<div id="modal-root">${modalContent()}</div><div id="toast-region" class="toast-region" aria-live="polite" aria-atomic="true"></div>`;if(state.tab==='discover')applyDiscoverFilters();if(state.tab==='customers')applyCustomerFilter();}
  let toastTimer;
  function toast(message){const area=$('#toast-region');if(!area)return;area.innerHTML=`<div class="toast"><div class="toast-check">${I('check')}</div><div>${escapeHTML(message)}</div></div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{const current=$('#toast-region');if(current)current.innerHTML='';},3800);}
  function commit(message){save();render();if(message)toast(message);}
  function applyDiscoverFilters(){const q=(state.searchQuery||'').toLowerCase().trim();$$('#discover-business-grid .business-card').forEach(card=>{const matches=card.dataset.search.includes(q);const category=card.querySelector('.business-category')?.textContent||'';const catMatch=state.categoryFilter==='Todos'||category===state.categoryFilter;card.style.display=matches&&catMatch?'':'none';});const grid=$('#discover-business-grid');if(grid&&!$$('#discover-business-grid .business-card').some(c=>c.style.display!=='none')){let no=grid.querySelector('.no-result');if(!no){no=document.createElement('div');no.className='no-result';no.textContent='No encontramos lugares con ese filtro. Prueba con otra búsqueda.';grid.appendChild(no);}no.style.display='';}else{const no=grid?.querySelector('.no-result');if(no)no.style.display='none';}}
  function applyCustomerFilter(){const q=($('[data-customer-search]')?.value||'').toLowerCase().trim();const body=$('#customer-table-body');if(!body)return;if(state.tab==='fidelidad'){const f=state.fidFilter||'todos';const r=fidSeed.filter(c=>c.name.toLowerCase().includes(q)&&(f==='inactivos'?fidInactive(c):f==='cerca'?(fidNear(c)||c.points>=REW):true)).sort((x,y)=>y.points-x.points);body.innerHTML=r.map(fidRow).join('')||'<tr><td colspan="7"><div class="empty-note">No encontramos clientes.</div></td></tr>';return;}const rows=[...customerSeed,...(state.customCustomers||[]).map(c=>({...c,status:'Registrado',last:c.last||'—',initials:c.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase(),tone:'green'}))].filter(c=>(c.name+' '+c.status).toLowerCase().includes(q));body.innerHTML=rows.map(customerRow).join('')||'<tr><td colspan="6"><div class="empty-note">No encontramos clientes.</div></td></tr>';}
  function openModal(type,extra={}){state.modal={type,...extra};render();}
  function switchMode(){const accountType=state.authUser?.accountType||'company';const toBusiness=!isAdmin();if(toBusiness&&accountType!=='company'){toast('Las cuentas de Usuario no pueden cambiar al modo Empresa.');return;}state.mode=toBusiness?'business':'customer';state.tab=toBusiness?'fidelidad':'home';state.modal=null;state.searchQuery='';commit(toBusiness?'Abriste el panel de negocio.':'Modo Usuario activado para pruebas. Puedes volver al modo Empresa cuando quieras.');}
  function toggleFollow(id){const b=businesses.find(x=>x.id===id);if(!b)return;const following=state.followed.includes(id);state.followed=following?state.followed.filter(x=>x!==id):[...state.followed,id];addActivity('review',following?'Dejaste de seguir un club':'Empezaste a seguir un club',b.name,following?'Actualizado':'Club nuevo');state.modal=null;commit(following?`Ya no sigues a ${b.name}.`:`Ahora sigues a ${b.name}.`);}
  function handleRsvp(id){const e=getEvent(id);if(!e)return;const going=state.rsvps.includes(id);state.rsvps=going?state.rsvps.filter(x=>x!==id):[...state.rsvps,id];if(!going)addActivity('event','Te interesa un evento',e.title,e.date);state.modal=null;commit(going?'Quitaste el evento de tus planes.':'Guardaste el evento en tus planes. Recuerda que es una confirmación de interés, no una reservación.');}
  function redeem(id){const r=rewardCatalog.find(x=>x.id===id);if(!r)return;if(state.redeemed.includes(id)){toast('Este beneficio ya se canjeó en esta demo.');return;}if(state.points<r.cost){toast(`Te faltan ${r.cost-state.points} puntos para este beneficio.`);return;}state.points-=r.cost;state.redeemed.push(id);addActivity('reward','Canjeaste una recompensa',`${r.title} · ${r.business}`,`-${r.cost} pts`);commit(`Canje de demostración completado: ${r.title}. No se ha enviado un cupón real.`);}
  function visitDemo(){if(state.lastDemoVisitDate===todayISO()){toast('Ya simulaste una visita hoy. Prueba de nuevo mañana.');return;}state.lastDemoVisitDate=todayISO();state.points+=10;addActivity('points','Simulaste una visita','Casa Luma Café · visita de demostración','+10 pts');commit('Visita simulada: sumaste 10 puntos de prueba.');}
  function createEvent(form){const fd=new FormData(form);const title=String(fd.get('title')||'').trim();const date=String(fd.get('date')||'');if(!title||!date){toast('Completa el nombre y la fecha del evento.');return;}const category=String(fd.get('category')||'Comunidad');const image=category==='Bienestar'?'https://images.unsplash.com/photo-1506126613408-eca07ce68773?auto=format&fit=crop&w=900&q=85':category==='Taller'?'https://images.unsplash.com/photo-1565193298595-6b6ce5b7b0d9?auto=format&fit=crop&w=900&q=85':category==='Mercadito'?'https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=900&q=85':'https://images.unsplash.com/photo-1445116572660-236099ec97a0?auto=format&fit=crop&w=900&q=85';const event={id:'ev-custom-'+Date.now(),title,category,date,time:String(fd.get('time')||'17:00'),location:String(fd.get('location')||'Casa Luma Café').trim(),price:String(fd.get('price')||'Entrada libre').trim(),host:'Casa Luma Café',description:String(fd.get('description')||'').trim(),image,attending:0};state.customEvents.push(event);state.modal=null;state.tab='events-admin';const today=getVisibleMonth();const eventMonth=getDayISO(event.date);state.calendarOffset=(eventMonth.getFullYear()-today.getFullYear())*12+(eventMonth.getMonth()-today.getMonth());state.selectedEventDate=event.date;commit('Evento creado en el prototipo. Todavía no se envían invitaciones ni se publica fuera de este navegador.');}
  function createCampaign(form){const fd=new FormData(form);const title=String(fd.get('title')||'').trim();const message=String(fd.get('message')||'').trim();const recipientId=String(fd.get('recipientId')||'').trim();const recipientName=String(fd.get('recipientName')||'').trim();if(!title||!message){toast('Completa el nombre y el mensaje de tu campaña.');return;}if(recipientName&&!recipientId){toast('Selecciona uno de los clientes sugeridos para confirmar a quién se enviará.');return;}const recipient=recipientId?allFidCustomers().find(c=>c.id===recipientId):null;state.campaigns.unshift({id:'camp-'+Date.now(),title,segment:String(fd.get('segment')),channel:String(fd.get('channel')),status:'Borrador',created:'Ahora',message,recipientId:recipient?.id||'',recipientName:recipient?.name||''});state.modal=null;state.tab='campaigns';commit(recipient?`Campaña preparada para ${recipient.name}. No se enviaron mensajes reales.`:'Campaña guardada como borrador. No se enviaron mensajes reales.');}
