  function handleAuth(form){const fd=new FormData(form),email=String(fd.get('email')||'').trim().toLowerCase(),password=String(fd.get('password')||''),users=state.users||[];if(state.authView==='register'){if(users.some(u=>u.email===email)){toast('Ya existe una cuenta con ese correo en este navegador.');return;}const accountType=String(fd.get('accountType')||state.registerType||'company');const user={id:'user-'+Date.now(),email,password,name:String(fd.get('name')||'').trim(),business:'',companyId:null,accountType};state.users=[...users,user];state.authUser={id:user.id,email:user.email,name:user.name,business:'',companyId:null,accountType};state.registerType=accountType;if(accountType==='user'){state.onboarding=null;state.mode='customer';state.tab='home';save();render();return;}state.onboarding={step:1,company:{},appearance:{color:'#c9a24a'},loyalty:{method:'purchase',earnEvery:10,goal:500},reward:{name:'',points:500,description:''},branch:{name:'Sucursal principal',address:'',city:'',phone:'',hours:'9:00 a 21:00'},team:{email:'',role:'Empleado'}};state.mode='business';save();render();}else{const user=users.find(u=>u.email===email&&u.password===password);if(!user){toast('No encontramos esa cuenta y contraseña en este navegador.');return;}state.authUser={id:user.id,email:user.email,name:user.name,business:user.business||'',companyId:user.companyId||null,accountType:user.accountType||'company'};state.mode=(user.accountType==='user')?'customer':'business';if(user.accountType==='user'){state.onboarding=null;state.tab='home';save();render();return;}if(!user.companyId||!state.company){state.onboarding={step:1,company:state.company||{name:user.business||''},appearance:{color:'#c9a24a'},loyalty:{...state.program,method:'purchase',earnEvery:state.program?.earnEvery||10,goal:state.program?.goal||500},reward:{name:state.program?.reward||'',points:state.program?.goal||500,description:''},branch:{name:'Sucursal principal',address:'',city:'',phone:'',hours:'9:00 a 21:00'},team:{email:'',role:'Empleado'}};}else{state.onboarding=null;state.tab='fidelidad';}save();render();}}
  function finishOnboarding(){const o=state.onboarding||{};const c=o.company||{};const company={id:'company-'+Date.now(),name:c.name||'Mi negocio',industry:c.industry||'Otro',phone:c.phone||'',city:c.city||'',address:c.address||'',brandName:o.appearance?.brandName||c.name||'Mi negocio',brandColor:o.appearance?.color||'#c9a24a',createdAt:todayISO()};state.company=company;state.authUser={...state.authUser,business:company.name,companyId:company.id};state.users=(state.users||[]).map(u=>u.id===state.authUser.id?{...u,business:company.name,companyId:company.id}:u);state.program={...state.program,earnEvery:Number(o.loyalty?.earnEvery||10),goal:Number(o.reward?.points||o.loyalty?.goal||500),reward:o.reward?.name||'Recompensa inicial'};state.settings={...(state.settings||{}),industry:company.industry};state.companySetup={...(state.companySetup||{}),operations:o.operations||{},appearance:o.appearance||{},team:o.team||{},setupCompletedAt:new Date().toISOString()};state.businessLocations=[{id:'loc-'+Date.now(),name:o.branch?.name||'Sucursal principal',address:o.branch?.address||company.address,city:o.branch?.city||company.city,phone:o.branch?.phone||company.phone,hours:o.branch?.hours||'9:00 a 21:00',map:'',active:true}];state.rewards=[{id:'reward-onb-'+Date.now(),name:o.reward?.name||'Recompensa inicial',points:Number(o.reward?.points||500),description:o.reward?.description||'Recompensa para nuevos miembros',status:'Activa',type:'Producto'} ,...(state.rewards||[])];state.auditLog=[{action:'Creó la empresa',detail:company.name,actor:state.authUser.email,date:new Date().toLocaleString('es-MX')},...(state.auditLog||[])];if(o.team?.email){state.pendingInvites=[{id:'inv-'+Date.now(),email:o.team.email,role:o.team.role||'Empleado',status:'Pendiente'} ,...(state.pendingInvites||[])];}state.onboarding=null;state.tab='fidelidad';commit('Tu Centro I.A. está listo.');}
