  function registerVisit(form){const fd=new FormData(form),customer=String(fd.get('customer')||'').trim(),date=String(fd.get('date')||todayISO()),points=Math.max(0,Number(fd.get('points')||0));if(!customer||!date){toast('Completa el nombre y la fecha de visita.');return;}const visit={id:'visit-'+Date.now(),customer,contact:String(fd.get('contact')||'').trim(),location:String(fd.get('location')||'Local principal'),date,points,notes:String(fd.get('notes')||'').trim()};state.visitCalendar=state.visitCalendar||[];state.visitCalendar.unshift(visit);state.pointLedger=state.pointLedger||[];state.pointLedger.unshift(visit);state.auditLog=state.auditLog||[];state.auditLog.unshift({action:'Registró visita y puntos',detail:`${customer} · +${points} pts`,actor:state.authUser?.email||'Administrador',date:new Date().toLocaleString('es-MX')});state.customCustomers=state.customCustomers||[];let c=state.customCustomers.find(x=>(visit.contact&&x.contact===visit.contact)||x.name.toLowerCase()===customer.toLowerCase());if(!c){c={id:'cc-'+Date.now(),name:customer,contact:visit.contact,visits:0,points:0,last:date};state.customCustomers.push(c);}c.visits=(c.visits||0)+1;c.points=(c.points||0)+points;c.last=date;addActivity('points',`Visita registrada: ${customer}`,`${visit.location} · ${date}`,`+${points} pts`);state.tab='visit-calendar';commit(`Visita registrada: ${customer} (+${points} puntos).`);}
